import{b as a,O as o,g as t,j as l}from"./chunks/framework.DcaUmd3X.js";const s=JSON.parse('{"title":"蛤蟆先生去看心理医生","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/mr-toad/index.md","filePath":"读书感悟/电子书架/44.蛤蟆先生去看心理医生.md","lastUpdated":1781614933000}'),i={name:"reading/digital/mr-toad/index.md"};function r(d,e,c,n,_,p){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="蛤蟆先生去看心理医生" tabindex="-1">蛤蟆先生去看心理医生 <a class="header-anchor" href="#蛤蟆先生去看心理医生" aria-label="Permalink to &quot;蛤蟆先生去看心理医生&quot;">​</a></h1><p><code>罗伯特·戴博德</code> <code>心理学应用</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 因为只有在那个时候，你才能思考当下的事情，评估自己的行为，或者倾听别人对你的看法而不马上驳斥，当然这一点很难做到。</p></blockquote><blockquote><p>📌 苍鹭接着说：“这是一个坐标图，上面有四个‘人生坐标’，就是我刚才所描述的四种情况。我们现在要做的就是探究并梳理出这四种情况的含义。”</p></blockquote><blockquote><p>📌 概括而言，他们都有强大的自我意识，了解自己的情感。他们能管理情绪，能从悲伤和不幸中重新振作。但也许最重要的是，他们能控制冲动，也懂得延迟满足，从而避免轻率的决定和不妥的行为。</p></blockquote><blockquote><p>📌 情感智力能让你在自我成长和完善的路上走得更远，因为它将带你从独立的个体走向共生的关系。</p></blockquote><blockquote><p>📌 人们太容易让重要的事件就这么过去，忘记关注或为它们庆祝，也许是因为我们通常都只在事后才明白它们有多重要。</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>📌 困惑是学习过程的第一阶段，这说明固有知识的局限开始被打破了。你要直面新的信息，这些新的信息会挑战你现有的观念和行为模式。</p><p>💭 勇敢的走出舒适区就对了</p></blockquote><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><blockquote><p>三种自我状态 (PAC 模型，沟通分析 TA 理论) 每个人身上都同时存在三种状态，决定你的情绪与行为:</p><ul><li>儿童自我状态 (Child) 像孩子一样感受与反应，分两种: 自然型儿童: 快乐、愤怒、悲伤、恐惧，真实情绪流露。适应型儿童: 为讨好父母/权威，压抑情绪、顺从、道歉、自我否定 (蛤蟆的主导状态)。特点: 情绪化、依赖、重复童年模式。</li><li>父母自我状态 (Parent) 内化父母/权威的价值观与评判，分两种: 挑剔型父母: 批判、指责、控制、高标准 (獾的主导状态)。养育型父母: 关爱、保护、支持。特点: 评判他人/自我、讲规矩、易愤怒。</li><li>成人自我状态 (Adult) 理性、客观、基于现实思考与决策，不被童年情绪或父母评判绑架。特点: 负责、独立、能学习与成长、主动选择。苍鹭说: 只有在成人自我状态，才能真正改变自己。人生坐标 (四象限) 童年形成的底层信念，回答两个问题: 我好吗? 你好吗?</li><li>我不好，你好 (蛤蟆初始状态): 自卑、讨好、受害者心态，总觉得自己不配、都是自己的错，易抑郁。</li><li>我好，你不好 (獾的状态): 傲慢、指责、控制，通过贬低他人抬高自己，易愤怒。</li><li>我不好，你也不好: 绝望、虚无、放弃，觉得人生无意义。</li><li>我好，你也好 (健康目标): 接纳自己、尊重他人，自信且友善，能建立平等关系</li></ul></blockquote>',12)])])}const b=a(i,[["render",r]]);export{s as __pageData,b as default};
